FILES = {'application.py': 'import os,json,sqlite3,uuid,sys,datetime\nfrom http.server import BaseHTTPRequestHandler,HTTPServer\nD=os.environ.get(\'DATA_DIR\',\'data\')\nPAGE=\'<!doctype html><title>Personal tasks</title><input id="x" aria-label="Task title" data-testid="task-title-input"><input id="d" type="date" aria-label="Due date" data-testid="task-due-input"><button data-testid="task-create-button" onclick="add()">Create task</button><ul id="list"></ul><script>\\nasync function api(m,p=\\\'\\\',v){let r=await fetch(\\\'/api/tasks\\\'+p,{method:m,body:v&&JSON.stringify(v)});if(!r.ok)throw Error(\\\'Invalid task\\\');return r.status==204?null:r.json()}\\nasync function add(){await api(\\\'POST\\\',\\\'\\\',{title:x.value,due_date:d.value||null});await show()}\\nfunction element(tag,test,label){let e=document.createElement(tag);e.dataset.testid=test;if(label)e.textContent=label;return e}\\nasync function show(){list.replaceChildren();for(let t of await api(\\\'GET\\\')){let row=element(\\\'li\\\',\\\'task-row\\\');row.dataset.taskId=t.id;let title=element(\\\'span\\\',\\\'task-title\\\');title.textContent=t.title;row.append(title,document.createTextNode(\\\' \\\'+(t.due_date||\\\'\\\')));\\nlet edit=element(\\\'button\\\',\\\'task-edit-button\\\',\\\'Edit\\\');edit.onclick=()=>{let a=element(\\\'input\\\',\\\'task-title-edit\\\'),b=element(\\\'input\\\',\\\'task-due-edit\\\'),save=element(\\\'button\\\',\\\'task-save-button\\\',\\\'Save\\\');a.value=t.title;b.type=\\\'date\\\';b.value=t.due_date||\\\'\\\';save.onclick=async()=>{await api(\\\'PATCH\\\',\\\'/\\\'+t.id,{title:a.value,due_date:b.value||null});await show()};row.replaceChildren(a,b,save)};\\nlet toggle=element(\\\'button\\\',\\\'task-complete-toggle\\\',t.completed?\\\'Reopen\\\':\\\'Complete\\\');toggle.onclick=async()=>{await api(\\\'PATCH\\\',\\\'/\\\'+t.id,{completed:!t.completed});await show()};let remove=element(\\\'button\\\',\\\'task-delete-button\\\',\\\'Delete\\\');remove.onclick=async()=>{await api(\\\'DELETE\\\',\\\'/\\\'+t.id);await show()};row.append(edit,toggle,remove);list.append(row)}}show()</script>\'\ndef db():\n os.makedirs(D,exist_ok=True);c=sqlite3.connect(D+\'/tasks.sqlite3\');c.execute(\'create table if not exists tasks(id text primary key,v text)\');return c\nclass H(BaseHTTPRequestHandler):\n def reply(self,n,v):\n  b=v.encode() if isinstance(v,str) else json.dumps(v).encode();b=b\'\' if n==204 else b\n  self.send_response(n);self.send_header(\'Content-Length\',str(len(b)));self.send_header(\'Content-Type\',\'text/html\' if isinstance(v,str) else \'application/json\');self.end_headers();self.wfile.write(b)\n def handle_task(self):\n  m=self.command;p=self.path\n  if p==\'/\' and m==\'GET\':return self.reply(200,PAGE)\n  if not(p==\'/api/tasks\' or p.startswith(\'/api/tasks/\')):return self.reply(404,{})\n  i=p[11:] if p.startswith(\'/api/tasks/\') else None\n  try:\n   v=json.loads(self.rfile.read(int(self.headers.get(\'Content-Length\',0))) or b\'{}\')\n   if not isinstance(v,dict):raise ValueError()\n   if (\'title\' in v or m==\'POST\'):\n    if not isinstance(v.get(\'title\'),str) or not 1<=len(v[\'title\'].strip())<=200:raise ValueError()\n    v[\'title\']=v[\'title\'].strip()\n   if \'completed\' in v and type(v[\'completed\']) is not bool:raise ValueError()\n   if v.get(\'due_date\') is not None:\n    if not isinstance(v[\'due_date\'],str) or datetime.date.fromisoformat(v[\'due_date\']).isoformat()!=v[\'due_date\']:raise ValueError()\n   if set(v)-{\'title\',\'due_date\',\'completed\'}:raise ValueError()\n   if m in (\'PATCH\',\'DELETE\') and not i:raise ValueError()\n  except (ValueError,TypeError):return self.reply(400,{})\n  with db() as c:\n   row=c.execute(\'select v from tasks where id=?\',(i,)).fetchone()\n   if i and not row:return self.reply(404,{})\n   if m==\'GET\':return self.reply(200,json.loads(row[0]) if i else [json.loads(r[0]) for r in c.execute(\'select v from tasks\')])\n   if m==\'DELETE\':c.execute(\'delete from tasks where id=?\',(i,));c.commit();return self.reply(204,{})\n   if m==\'POST\':i=uuid.uuid4().hex;t=dict(id=i,title=v[\'title\'],due_date=v.get(\'due_date\'),completed=False)\n   elif m==\'PATCH\':\n    t=json.loads(row[0]);t.update({k:v[k] for k in (\'title\',\'due_date\',\'completed\') if k in v})\n   else:return self.reply(405,{})\n   c.execute(\'insert or replace into tasks values(?,?)\',(i,json.dumps(t)));c.commit();self.reply(201 if m==\'POST\' else 200,t)\n do_GET=do_POST=do_PATCH=do_DELETE=handle_task\nif __name__==\'__main__\':HTTPServer((\'127.0.0.1\',int(os.environ.get(\'PORT\',\'8080\'))),H).serve_forever()\n', 'test_core.py': "import unittest,tempfile,threading,http.client,json,application\nclass Core(unittest.TestCase):\n def test_core(self):\n  with tempfile.TemporaryDirectory() as directory:\n   application.D=directory;s=application.HTTPServer(('127.0.0.1',0),application.H);threading.Thread(target=s.serve_forever,daemon=True).start()\n   def call(method,path='/api/tasks',v=None):\n    c=http.client.HTTPConnection('127.0.0.1',s.server_port);c.request(method,path,json.dumps(v) if v is not None else None);r=c.getresponse();b=r.read();c.close();return r.status,json.loads(b) if b else None\n   try:\n    n,t=call('POST',v={'title':'unit','due_date':'2027-01-01'});self.assertEqual(n,201);p='/api/tasks/'+t['id']\n    self.assertTrue(call('PATCH',p,{'title':'edited','completed':True})[1]['completed']);self.assertEqual(call('GET',p)[1]['title'],'edited')\n    with application.db() as c:self.assertIn('edited',c.execute('select v from tasks').fetchone()[0])\n    self.assertEqual(call('POST',v={'title':'bad','due_date':'2027-02-30'})[0],400)\n    self.assertEqual(call('DELETE',p)[0],204);self.assertEqual(call('GET',p)[0],404)\n   finally:s.shutdown();s.server_close()\n", 'run-app': '#!/bin/sh\nexec python3 -B /app/application.py\n', 'run-tests': '#!/bin/sh\ncd /app\nexec python3 -B -m unittest -v\n', 'README.md': 'TEST DOUBLE: ./run-app; ./run-tests.\n'}
